            front_s = nxt
        else:
            nxt = set()
            for cell in front_g:
                for nb in neighbours(cell):
                    if nb not in par_g:
                        par_g[nb] = cell
                        nxt.add(nb)
                        if nb in par_s:
                            meet = nb
            front_g = nxt
    if meet is None:
